node -e "
const toRad = deg => deg * Math.PI / 180;

// Location 1: Device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Location 2: Shipping address — Boston, MA 02118 (approximate geocode)
const lat2 = 42.3396, lon2 = -71.0693;

// Haversine formula
const R_km = 6371;
const R_mi = 3958.8;

const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 +
          Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
          Math.sin(dLon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

const distKm = (R_km * c).toFixed(2);
const distMi = (R_mi * c).toFixed(2);

console.log('=== Distance Calculation ===');
console.log();
console.log('  📍 From: (37.7749, -122.4194) — San Francisco, CA');
console.log('  📍 To:   4829 Elm Ridge Way, Suite 7, Boston, MA 02118, USA');
console.log('           (approx. 42.3396, -71.0693)');
console.log();
console.log('  📏 Straight-line (great-circle) distance:');
console.log('     • ' + Number(distKm).toLocaleString() + ' km');
console.log('     • ' + Number(distMi).toLocaleString() + ' miles');
console.log();
console.log('  ℹ️  Note: This is the as-the-crow-flies distance.');
console.log('     Actual driving/shipping distance is typically longer (~3,100 mi / ~4,990 km).');
"
